# approve_members.py: approve handshakes from marketplace members only
import json, subprocess

NETWORK_ID = "7"  # your marketplace network

def pilotctl(*args):
    out = subprocess.run(["pilotctl", "--json", *args], capture_output=True, text=True, check=True)
    return json.loads(out.stdout)["data"]

members = {n["node_id"] for n in pilotctl("network", "members", NETWORK_ID).get("nodes", [])}
for req in pilotctl("pending")["pending"]:
    node = str(req["node_id"])
    if req["node_id"] in members:
        pilotctl("approve", node)
    else:
        pilotctl("reject", node, "members of the marketplace network only")

#!/usr/bin/env python3
"""Marketplace worker: answers code-review jobs that arrive in the Pilot inbox."""
import json
import subprocess
import time

POLL_INTERVAL = 5  # seconds

def pilotctl(*args):
    """Run pilotctl --json and return the "data" field of its output."""
    out = subprocess.run(["pilotctl", "--json", *args], capture_output=True, text=True)
    if out.returncode != 0:
        raise RuntimeError(out.stderr.strip())  # JSON with code, message and hint
    return json.loads(out.stdout)["data"]

def review(job):
    # Your actual review logic: call a model, run static analysis, etc.
    return {"type": "review_result", "job": job.get("job"), "findings": [], "summary": "no findings"}

def main():
    seen = set()
    while True:
        inbox = pilotctl("inbox", "--full", "--limit", "0")
        for msg in inbox["messages"]:
            if msg["id"] in seen:
                continue
            seen.add(msg["id"])
            try:
                job = json.loads(msg.get("data", ""))
            except ValueError:
                continue
            if job.get("type") != "review_request":
                continue
            result = review(job)
            pilotctl("send-message", msg["from"], "--type", "json",
                     "--data", json.dumps(result),
                     "--reply-to", msg.get("message_id", msg["id"]))
        time.sleep(POLL_INTERVAL)

if __name__ == "__main__":
    main()

# ledger.py: the requester's own record of how each worker did
import sqlite3, time

db = sqlite3.connect("ledger.db")
db.execute("CREATE TABLE IF NOT EXISTS jobs (worker TEXT, public_key TEXT, ok INTEGER, seconds REAL, at REAL)")

def record(worker, public_key, ok, seconds):
    db.execute("INSERT INTO jobs VALUES (?, ?, ?, ?, ?)", (worker, public_key, int(ok), seconds, time.time()))
    db.commit()

def score(worker):
    # (success rate, jobs seen)
    return db.execute("SELECT AVG(ok), COUNT(*) FROM jobs WHERE worker = ?", (worker,)).fetchone()
